from lib import *
S = SS('h15')
steps = [
    step("同一个服务器、不同写法的 target(我在本机起了一个只回答 svc.test 的小 DNS 服务器,A 记录是三个假 IP 10.9.0.1~3,自定义 dialer 把假 IP 映射到本机真实后端)。passthrough:///svc.test:7000:DNS 查询 0 个,dialer 直接收到字符串“svc.test:7000”——名字原样交给 dialer。dns://<DNS>/svc.test:7000:DNS 服务器收到 A 1 个、AAAA 1 个、TXT 2 个查询,dialer 收到的是解析后的 10.9.0.1:7000。dns://<DNS>/svc.test(不写端口):dialer 收到 10.9.0.1:443——默认端口 443。dns:///10.9.0.1:7000(IP 字面量):0 个 DNS 查询。裸写 svc.test:7000(没有 scheme):0 个查询到我的 DNS 服务器,调用失败 Unavailable“name resolver error: produced zero addresses”——没有 scheme 的 target 没有查到我的 DNS 服务器(应该是走了 dns 解析器的系统解析,这一点没有单独验证)。", t=tl(S(1)), done=lidx(S(1), 'svc.test:7000   '), mark=lidx(S(1), 'passthrough:'), b=bars([['passthrough 的 DNS 查询数', 0, '0'], ['dns 的 A 查询数', 1, '1'], ['dns 的 TXT 查询数', 2, '2']], 3, mark=[0], done=[1, 2]), kv=KV([['passthrough', '不解析,名字原样给 dialer'], ['dns', 'A + AAAA + TXT 查询;默认端口 443'], ['没有 scheme', 'NewClient 用 dns(系统解析)']], ['dns'])),
    step("一个域名三条 A 记录、客户端指定 round_robin:90 次调用各后端收到 [30 30 30],dialer 依次收到 10.9.0.1、10.9.0.3、10.9.0.2 三个地址(同一个域名的所有 IP 都建了连接)。启动时 DNS 服务器收到的查询:A 1 个、AAAA 1 个、TXT 2 个;名字是 svc.test. 的 A、AAAA,以及 _grpc_config.svc.test. 和 _grpc_config.svc.test.lan. 的 TXT(第二个带 .lan 是这台机器的系统搜索域,Go 的解析器在第一个没有结果时补上去的,别的机器上不一定出现)。", t=tl(S(2)), done=lidx(S(2), '查询的名字'), mark=lidx(S(2), '90 次调用各后端'), b=bars([['后端 1 收到', 30, '30'], ['后端 2 收到', 30, '30'], ['后端 3 收到', 30, '30']], 32, done=[0, 1, 2]), kv=KV([['一个域名 → 地址', '3 条 A 记录 = 3 个地址'], ['启动时的查询', 'A、AAAA、_grpc_config 的 TXT'], ['搜索域', '这台机器多出 .lan 的 TXT 查询']], ['一个域名 → 地址'])),
    step("DNS 里的 TXT 记录可以带服务配置:在 _grpc_config.svc.test 的 TXT 里写 grpc_config=[{\"serviceConfig\":{\"loadBalancingConfig\":[{\"round_robin\":{}}]}}],客户端不设任何默认配置。默认环境下 30 次调用各后端收到 [9 10 11]——TXT 里的 round_robin 生效了;设环境变量 GRPC_ENABLE_TXT_SERVICE_CONFIG=false 后是 [30 0 0](pick_first),DNS 查询里也没有了 TXT。也就是说,在这个版本(grpc-go v1.84.0)里服务配置默认会从 DNS 的 TXT 记录里读;能被 DNS 的维护者改变客户端行为,这是安全上要留意的一点,不需要的话可以用这个环境变量关掉。", t=tl(S(3)), done=lidx(S(3), 'GRPC_ENABLE_TXT_SERVICE_CONFIG=false'), mark=lidx(S(3), '默认环境'), b=bars([['默认:后端 1 收到', 9, '9'], ['默认:后端 2 收到', 10, '10'], ['默认:后端 3 收到', 11, '11'], ['关掉 TXT:后端 1 收到', 30, '30']], 32, mark=[3], done=[0, 1, 2]), kv=KV([['默认', 'TXT 里的 round_robin 生效 [9 10 11]'], ['GRPC_ENABLE_TXT_SERVICE_CONFIG=false', 'pick_first [30 0 0],不再查 TXT'], ['源码', 'envconfig.EnableTXTServiceConfig,默认开']], ['默认'])),
    step("什么时候重新解析 DNS(默认 MinResolutionInterval = 30 秒;A 记录的 TTL 设成 1 秒)。2 秒时把记录从 [1 2 3] 换成 [3 4 5],6 秒时停掉当前在用的后端 1,每 100 ms 调用一次共 36 秒:A 查询只出现了一次,在 30.0 秒。0–2 秒后端集合 [1 2 3];2–6 秒记录已经换了、客户端仍在用 [1 2 3](TTL 1 秒被无视);6 秒停掉后端 1 之后到 30.0 秒,后端集合是 [2 3],失败 0 次;30.0 秒重新解析之后才出现 [3 4 5]。读源码:解析成功之后,watcher 只等 ResolveNow(连接出问题时由连接管理触发),并且距上一次解析至少隔 MinResolutionInterval,所以连接断开的 6 秒触发了重新解析请求,但要等到 30.0 秒才真正去查。", t=tl(S(4)), done=lidx(S(4), '最后一次 A 查询之后'), mark=lidx(S(4), 'DNS 的 A 查询时刻'), b=bars([['A 查询出现的时刻 s', 30.0, '30.0'], ['后端 1 停掉的时刻 s', 6, '6']], 32, mark=[1], done=[0]), kv=KV([['TTL', '1 秒,被无视'], ['记录 2 秒时改了', '30.0 秒才看到'], ['后端停掉(6 秒)', '触发重新解析请求,但要等到 30.0 秒']], ['TTL'])),
    step("同样的场景,用 dns.SetMinResolutionInterval(1 秒)把最小间隔改成 1 秒(共 14 秒):A 查询出现在 6.0 和 7.0 秒——后端停掉的当下就重新解析了,6–7 秒的后端集合是 [2 3 4 5](新地址 4、5 已经加进来),7.0 秒之后 [3 4 5],失败 0 次;但 2 秒时记录改了,到 6.0 秒之前客户端仍然只看见 [1 2 3]。结论:grpc-go 的 DNS 解析器不主动轮询、不看 TTL,只在连接出问题时重新解析,并且受最小间隔限制;要“及时感知后端变化”,不能依赖 DNS 的轮询(第 16 篇)。", t=tl(S(5)), done=lidx(S(5), '最后一次 A 查询之后'), mark=lidx(S(5), 'DNS 的 A 查询时刻'), b=bars([['第 1 次 A 查询的时刻 s', 6.0, '6.0'], ['第 2 次 A 查询的时刻 s', 7.0, '7.0']], 8, mark=[0], done=[1]), kv=KV([['最小间隔 1 秒', '后端停掉后 6.0 秒立刻重新解析'], ['重新解析之后', '[3 4 5],新地址被用上'], ['2 秒时改的记录', '到 6.0 秒才被发现']], ['最小间隔 1 秒'])),
    step("DNS 解析失败时:域名不存在(NXDOMAIN)。fail-fast 的调用 2.3 ms 后返回 Unavailable“name resolver error: produced zero addresses”;重试解析的 A 查询出现在 0.0、1.7、4.0 秒(每次其实是两个名字:svc.test. 和带搜索域的 svc.test.lan.),间隔会越来越长;3 秒时我把记录加上,先发起的 WaitForReady 调用 4.0 秒后返回 code=OK——等的是下一次重试解析(4.0 秒),而不是 3 秒记录一加上就成功。解析失败期间解析器自己做指数退避重试。", t=tl(S(6)), done=lidx(S(6), '整个过程 A 查询时刻'), mark=lidx(S(6), 'fail-fast 调用'), b=bars([['fail-fast 调用返回用时 ms', 2.3, '2.3'], ['WaitForReady 返回的时刻 s', 4.0, '4.0']], 5, mark=[0], done=[1]), kv=KV([['fail-fast', 'Unavailable: produced zero addresses'], ['A 查询时刻', '0.0、1.7、4.0 秒(退避)'], ['记录 3 秒加上', '4.0 秒下一次重试才成功']], ['A 查询时刻'])),
    step("域名存在、但一条 A 记录都没有(NOERROR 空答案):fail-fast 的调用 0.7 ms 返回 Unavailable,message 同样是“name resolver error: produced zero addresses”。所以“域名不存在”和“域名存在但没有记录”在客户端看来是同一个错误,排查时要看 DNS 本身。", t=tl(S(7)), done=lidx(S(7), 'fail-fast 调用'), mark=lidx(S(7), 'fail-fast 调用'), b=bars([['返回用时 ms', 0.7, '0.7']], 1, done=[0]), kv=KV([['NXDOMAIN', 'produced zero addresses'], ['空答案', 'produced zero addresses'], ['区别', '客户端看不出来']], ['区别'])),
]
A = mkarth('h15', 15, 'gRPC,名字解析,DNS,passthrough,TXT,服务配置,重新解析,Go,真实验证,动画演示',
    '实测 gRPC 的名字解析:passthrough 与 dns 的差别、默认端口、一个域名多条 A 记录、DNS TXT 里的服务配置默认生效、TTL 被无视、重新解析的时机受 30 秒最小间隔限制、解析失败的表现。',
    'grpc-go 解析 dns:/// 目标时,到底查了什么、什么时候重新查、TTL 起不起作用?域名不存在时调用会怎样?这篇在本机起了一个小 DNS 服务器,把每个查询都记下来。',
    [('30.0 秒', '默认设置下,后端 6 秒时停掉后,DNS 重新解析真正发出的时刻(记录 2 秒时就改了)'), ('[9 10 11] vs [30 0 0]', 'DNS TXT 里写的 round_robin 在默认环境生效;关掉环境变量后退回 pick_first'), ('443', '写 dns:///svc.test 不带端口时 dialer 收到的端口')],
    [('两个常用的解析器', '<p>passthrough 不解析,把名字原样交给 dialer;dns 解析成 IP,一个域名下的所有 A 记录都成为地址。没有 scheme 的 target,NewClient 当作 dns。</p>'),
     ('查了什么', '<p>启动时对域名发 A、AAAA 查询,另外还会查 _grpc_config.&lt;域名&gt; 的 TXT(服务配置)。不写端口时默认 443。</p>'),
     ('TXT 里的服务配置', '<p>在这个版本里默认读取并应用 DNS TXT 里的服务配置(如负载均衡策略)。不想让 DNS 改变客户端行为,用 GRPC_ENABLE_TXT_SERVICE_CONFIG=false 关掉。</p>'),
     ('不看 TTL、不轮询', '<p>解析成功后,解析器只等连接管理发来的“重新解析”请求,并且两次解析至少隔 30 秒(可用 dns.SetMinResolutionInterval 调整)。DNS 记录改了,客户端不会马上知道。</p>'),
     ('改小最小间隔', '<p>改成 1 秒后,连接出问题的当下就会重新解析并用上新地址。但没有连接问题时仍然不会主动查询。</p>'),
     ('解析失败', '<p>域名不存在时,调用立即以 Unavailable 失败;解析器按指数退避重试。WaitForReady 的调用会等到某次重试成功。</p>'),
     ('空答案', '<p>域名存在但没有 A 记录,与域名不存在的错误信息相同(produced zero addresses)。</p>')],
    steps,
    [ENV_H + '。DNS 服务器是我用 golang.org/x/net/dns/dnsmessage 写的、只监听本机 UDP 的小程序,每个查询都被记录;A 记录给的是假 IP 10.9.0.x,由自定义 dialer 映射到本机真实后端,所以验证的是解析与地址选择,不涉及真实网络;TXT 实验用子进程设置环境变量;读源码确认:watcher 在解析成功后等待 ResolveNow 且至少间隔 MinResolutionInterval(internal/resolver/dns/dns_resolver.go)',
     '没有验证:系统解析器(没有 scheme 的 target 实际去问了谁,以及它的错误是什么);SRV/grpclb 的查询(默认关闭);IPv6 的 AAAA 记录有内容时的行为;大量 A 记录(超过 UDP 报文大小、需要 TCP 回落)时的行为;真实 DNS 缓存/负载均衡 DNS 的行为;重试退避的具体参数(只观察到 0.0、1.7、4.0 这一次运行的时刻)'],
    '名字解析')
